import { AlertTriangle, Landmark, ReceiptText, Scale } from 'lucide-react';

import { ActionMenu } from '../../components/action-menu';
import { AdminFilterPanel } from '../../components/admin-filter-panel';
import { AdminFilterSummary } from '../../components/admin-filter-summary';
import { AdminPageTemplate } from '../../components/admin-page-template';
import { AdminSection } from '../../components/admin-surface';
import { MoneyText } from '../../components/money-text';
import type { AdminMonthlyTaxClosingSummary } from '../../lib/admin-api';
import { adminGetResult } from '../../lib/admin-api';
import { FinanceOverviewTablePanel, type FinanceOverviewTableRow } from './finance-overview-table-panel';
import { FinancePeriodFilterForm } from './finance-period-filter-form';
import { FinanceListCommandBoard, FinanceListCommandCard } from './finance-list-command-card';
import {
  bookingSettlementAuditHref,
  buildMonthlyTaxClosingSummaryApiHref,
  couponFinanceHref,
  emptyMonthlyTaxClosingSummary,
  generalLedgerHref,
  monthlyTaxClosingHref,
  partnerWithholdingTaxHref,
  paymentFeeHref,
  platformVatHref,
  readBookingSettlementFilters,
  readFinanceAccountingFilters,
  readMonthlyTaxClosingFilters,
  readPartnerWithholdingTaxFilters,
} from './tax-settlement-page-model';

type FinanceTaxPageProps = {
  readonly searchParams?: Promise<Record<string, string | string[] | undefined>>;
};

export default async function FinanceTaxPage({ searchParams }: FinanceTaxPageProps) {
  const params = searchParams ? await searchParams : {};
  const monthlyFilters = readMonthlyTaxClosingFilters(params);
  const settlementFilters = {
    ...readBookingSettlementFilters(params),
    page: 1,
    period: monthlyFilters.period,
    range: 'all' as const,
  };
  const withholdingFilters = {
    ...readPartnerWithholdingTaxFilters(params),
    page: 1,
    period: monthlyFilters.period,
  };
  const accountingFilters = {
    ...readFinanceAccountingFilters(params, 'posted'),
    page: 1,
    range: 'all' as const,
  };
  const summaryResult = await adminGetResult<AdminMonthlyTaxClosingSummary>(
    buildMonthlyTaxClosingSummaryApiHref(monthlyFilters),
    emptyMonthlyTaxClosingSummary(monthlyFilters.period),
  );

  if (!summaryResult.ok) {
    return <TaxCloseUnavailable period={monthlyFilters.period} status={summaryResult.status} />;
  }

  const summary = summaryResult.data;
  const formulaIssueCount = Number(summary.reconciliationDelta !== 0) + Number(summary.netRevenueDelta !== 0);
  const closeoutGateCount =
    summary.openTaxCount +
    summary.paymentFeeReviewFlagCount +
    summary.couponReviewFlagCount +
    summary.partnerDepositReconciliationOpenCount +
    summary.payoutBankOutflowReconciliationOpenCount +
    summary.payoutReturnInflowReconciliationOpenCount +
    formulaIssueCount;
  const periodScope = `Month ${summary.period}`;
  const closeoutRows = buildCloseoutRows({
    formulaIssueCount,
    monthlyFilters,
    settlementFilters,
    summary,
  });
  const recordRows = buildRecordRows({
    accountingFilters,
    monthlyFilters,
    settlementFilters,
  });

  return (
    <AdminPageTemplate
      actions={
        <ActionMenu
          actions={[
            {
              href: '/finance-overview',
              kind: 'link',
              label: 'Finance Overview',
              tone: 'info',
            },
            {
              href: monthlyTaxClosingHref(monthlyFilters),
              kind: 'link',
              label: 'Monthly Close',
              tone: 'neutral',
            },
            {
              href: generalLedgerHref(accountingFilters),
              kind: 'link',
              label: 'General Ledger',
              tone: 'neutral',
            },
          ]}
          label="Tax and close navigation"
          variant="button-list"
        />
      }
      description="Monthly VAT, Partner withholding, payment fees, and closeout risks for one Vietnam accounting period."
      metrics={[
        {
          helper: 'Current stored close status, or draft while the month remains open.',
          href: monthlyTaxClosingHref(monthlyFilters),
          kind: summary.status === 'CLOSED' ? 'record' : 'action',
          label: 'Close status',
          scope: periodScope,
          value: summary.status,
        },
        {
          helper: 'Company output VAT recognized from HANDS platform fee.',
          href: platformVatHref(monthlyFilters),
          kind: 'period',
          label: 'Platform VAT',
          scope: periodScope,
          value: <MoneyText amount={summary.companyOutputVatTotal} currency={summary.currency} />,
        },
        {
          helper: 'Partner VAT and PIT retained for declaration and remittance.',
          href: partnerWithholdingTaxHref(withholdingFilters),
          kind: 'period',
          label: 'Partner withholding',
          scope: periodScope,
          value: <MoneyText amount={summary.partnerWithholdingTotal} currency={summary.currency} />,
        },
      ]}
      title="Tax & Close Overview"
    >
      <FinanceListCommandBoard ariaLabel="Tax and close command board">
        <FinanceListCommandCard
          detail="Open settlement, fee, coupon, deposit, or formula checks still blocking the selected month."
          href={monthlyTaxClosingHref(monthlyFilters)}
          icon={AlertTriangle}
          label="Closeout gates"
          scope={closeoutGateCount > 0 ? 'Needs action' : periodScope}
          tone={closeoutGateCount > 0 ? 'danger' : 'success'}
          value={String(closeoutGateCount)}
        />
        <FinanceListCommandCard
          detail="Company VAT payable from platform-fee settlement records."
          href={platformVatHref(monthlyFilters)}
          icon={ReceiptText}
          label="Platform VAT"
          scope={periodScope}
          tone={summary.companyOutputVatTotal > 0 ? 'warning' : 'neutral'}
          value={<MoneyText amount={summary.companyOutputVatTotal} currency={summary.currency} />}
        />
        <FinanceListCommandCard
          detail="Partner VAT and PIT retained for declaration and remittance."
          href={partnerWithholdingTaxHref(withholdingFilters)}
          icon={Landmark}
          label="Partner withholding"
          scope={periodScope}
          tone={summary.partnerWithholdingTotal > 0 ? 'warning' : 'neutral'}
          value={<MoneyText amount={summary.partnerWithholdingTotal} currency={summary.currency} />}
        />
        <FinanceListCommandCard
          detail="Payment processing fees recorded for the selected accounting month."
          href={paymentFeeHref(monthlyFilters)}
          icon={Scale}
          label="Payment fees"
          scope={periodScope}
          tone={summary.paymentFeeReviewFlagCount > 0 ? 'warning' : 'info'}
          value={<MoneyText amount={summary.paymentProcessingFeeTotal} currency={summary.currency} />}
        />
      </FinanceListCommandBoard>

      <AdminFilterPanel
        className="admin-mb-16"
        description="Changing the month updates every VAT, withholding, fee, and closeout figure on this page."
        resultLabel={`${summary.period} · ${summary.status}`}
        resultTone={summary.status === 'CLOSED' ? 'success' : 'info'}
        title="Accounting month"
      >
        <FinancePeriodFilterForm
          action="/finance-tax"
          period={monthlyFilters.period}
          submitLabel="Apply month"
        />
        <AdminFilterSummary
          ariaLabel="Active tax and close filters"
          labels={[`Month: ${summary.period}`, `Close status: ${summary.status}`]}
          tone="info"
        />
      </AdminFilterPanel>

      <FinanceOverviewTablePanel
        description="Non-zero checks appear first. Resolve these before declaring, paying, or closing the month."
        resultLabel={`${closeoutGateCount} open check(s)`}
        resultTone={closeoutGateCount > 0 ? 'warning' : 'success'}
        rows={closeoutRows}
        title="Monthly closeout checks"
      />

      <FinanceOverviewTablePanel
        description="Historical evidence stays outside the daily Finance command view and opens only when record-level review is needed."
        resultLabel={`${recordRows.length} record workspaces`}
        resultTone="info"
        rows={recordRows}
        title="Accounting records"
      />
    </AdminPageTemplate>
  );
}

function TaxCloseUnavailable({
  period,
  status,
}: {
  readonly period: string;
  readonly status: number | null;
}) {
  return (
    <AdminPageTemplate
      description={`Monthly tax and close totals for ${period} could not be loaded.`}
      title="Tax & Close Overview"
    >
      <AdminSection
        actions={<AlertTriangle aria-hidden="true" size={18} />}
        className="admin-mb-16"
        description="Tax amounts and closeout counts are intentionally hidden so unavailable data is never mistaken for 0 VND or zero pending records."
        statusLabel={status ? `API ${status}` : 'API unavailable'}
        statusTone="danger"
        title="Tax and close data unavailable"
      >
        <ActionMenu
          actions={[
            {
              href: `/finance-tax?${new URLSearchParams({ period }).toString()}`,
              kind: 'link',
              label: 'Retry tax and close overview',
              tone: 'danger',
            },
            {
              href: '/finance-overview',
              kind: 'link',
              label: 'Open Finance Overview',
              tone: 'info',
            },
          ]}
          label="Tax and close unavailable actions"
          variant="button-list"
        />
      </AdminSection>
    </AdminPageTemplate>
  );
}

function buildCloseoutRows({
  formulaIssueCount,
  monthlyFilters,
  settlementFilters,
  summary,
}: {
  readonly formulaIssueCount: number;
  readonly monthlyFilters: ReturnType<typeof readMonthlyTaxClosingFilters>;
  readonly settlementFilters: ReturnType<typeof readBookingSettlementFilters>;
  readonly summary: AdminMonthlyTaxClosingSummary;
}) {
  const rows: Array<FinanceOverviewTableRow & { count: number }> = [
    {
      actionLabel: 'Review',
      count: summary.openTaxCount,
      helper: 'Settlement rows still waiting for declaration, payment, or closeout.',
      href: bookingSettlementAuditHref({ ...settlementFilters, review: 'open' }),
      key: 'open-tax',
      label: 'Open tax rows',
      signal: 'TAX',
      signalTone: summary.openTaxCount > 0 ? 'warn' : 'ok',
      value: `${summary.openTaxCount} row(s)`,
    },
    {
      actionLabel: 'Review',
      count: summary.paymentFeeReviewFlagCount,
      helper: 'Settlement rows with missing or inconsistent payment-fee evidence.',
      href: paymentFeeHref(monthlyFilters),
      key: 'payment-fee',
      label: 'Payment fee evidence',
      signal: 'FEE',
      signalTone: summary.paymentFeeReviewFlagCount > 0 ? 'warn' : 'ok',
      value: `${summary.paymentFeeReviewFlagCount} flag(s)`,
    },
    {
      actionLabel: 'Review',
      count: summary.couponReviewFlagCount,
      helper: 'Coupon funding or expense records requiring monthly Finance review.',
      href: couponFinanceHref(settlementFilters),
      key: 'coupon',
      label: 'Coupon accounting',
      signal: 'COUPON',
      signalTone: summary.couponReviewFlagCount > 0 ? 'warn' : 'ok',
      value: `${summary.couponReviewFlagCount} flag(s)`,
    },
    {
      actionLabel: 'Reconcile',
      count: summary.partnerDepositReconciliationOpenCount,
      helper: 'Executed Partner deposits still missing complete company-bank evidence.',
      href: '/finance-tax/approval-queue?view=reconciliation',
      key: 'partner-deposit',
      label: 'Partner deposit reconciliation',
      signal: 'BANK',
      signalTone: summary.partnerDepositReconciliationOpenCount > 0 ? 'warn' : 'ok',
      value: (
        <>
          {summary.partnerDepositReconciliationOpenCount} ·{' '}
          <MoneyText amount={summary.partnerDepositReconciliationOpenAmount} currency={summary.currency} />
        </>
      ),
    },
    {
      actionLabel: 'Reconcile',
      count: summary.payoutBankOutflowReconciliationOpenCount,
      helper: 'Paid Partner payouts still missing a complete OUTFLOW match to their posted bank credit.',
      href: '/finance-tax/bank-reconciliation?workspace=operations&range=all&review=unmatched',
      key: 'payout-bank-outflow',
      label: 'Payout bank outflow',
      signal: 'OUTFLOW',
      signalTone: summary.payoutBankOutflowReconciliationOpenCount > 0 ? 'warn' : 'ok',
      value: (
        <>
          {summary.payoutBankOutflowReconciliationOpenCount} ·{' '}
          <MoneyText amount={summary.payoutBankOutflowReconciliationOpenAmount} currency={summary.currency} />
        </>
      ),
    },
    {
      actionLabel: 'Reconcile',
      count: summary.payoutReturnInflowReconciliationOpenCount,
      helper: 'Partner payout reversals still missing a complete INFLOW match to their posted bank debit.',
      href: '/finance-tax/bank-reconciliation?workspace=operations&range=all&review=unmatched',
      key: 'payout-return-inflow',
      label: 'Payout return inflow',
      signal: 'INFLOW',
      signalTone: summary.payoutReturnInflowReconciliationOpenCount > 0 ? 'warn' : 'ok',
      value: (
        <>
          {summary.payoutReturnInflowReconciliationOpenCount} ·{' '}
          <MoneyText
            amount={summary.payoutReturnInflowReconciliationOpenAmount}
            currency={summary.currency}
          />
        </>
      ),
    },
    {
      actionLabel: 'Review',
      count: formulaIssueCount,
      helper: 'Reconciliation and net-revenue formulas must both equal 0 VND.',
      href: monthlyTaxClosingHref(monthlyFilters),
      key: 'formula',
      label: 'Formula reconciliation',
      signal: 'FORMULA',
      signalTone: formulaIssueCount > 0 ? 'warn' : 'ok',
      value: (
        <MoneyText
          amount={Math.abs(summary.reconciliationDelta) + Math.abs(summary.netRevenueDelta)}
          currency={summary.currency}
        />
      ),
    },
  ];

  return rows
    .sort((left, right) => Number(right.count > 0) - Number(left.count > 0))
    .map((row) => ({
      actionLabel: row.actionLabel,
      helper: row.helper,
      href: row.href,
      key: row.key,
      label: row.label,
      signal: row.signal,
      signalTone: row.signalTone,
      value: row.value,
    }));
}

function buildRecordRows({
  accountingFilters,
  monthlyFilters,
  settlementFilters,
}: {
  readonly accountingFilters: ReturnType<typeof readFinanceAccountingFilters>;
  readonly monthlyFilters: ReturnType<typeof readMonthlyTaxClosingFilters>;
  readonly settlementFilters: ReturnType<typeof readBookingSettlementFilters>;
}): FinanceOverviewTableRow[] {
  return [
    {
      actionLabel: 'Open',
      helper: 'Posted booking amounts, payment method, Partner payout, VAT/PIT, and fee evidence.',
      href: bookingSettlementAuditHref(settlementFilters),
      key: 'settlements',
      label: 'Booking settlement records',
      signal: 'SETTLE',
      value: monthlyFilters.period,
    },
    {
      actionLabel: 'Open',
      helper:
        'Balanced debit and credit batches created by settlement, refund, payout, and adjustment flows.',
      href: generalLedgerHref(accountingFilters),
      key: 'ledger',
      label: 'General ledger',
      signal: 'GL',
      value: 'Posted batches',
    },
    {
      actionLabel: 'Open',
      helper: 'Closed-period corrections and refunds retained without editing the original settlement.',
      href: `/finance-tax/settlement-reversals?${new URLSearchParams({
        period: monthlyFilters.period,
        range: 'all',
        review: 'reversed',
      }).toString()}`,
      key: 'reversals',
      label: 'Settlement reversals',
      signal: 'REV',
      value: 'Reversal records',
    },
    {
      actionLabel: 'Open',
      helper: 'Versioned Vietnam tax rules. Historical settlement values remain immutable.',
      href: '/tax-policy',
      key: 'tax-policy',
      label: 'Tax policy',
      signal: 'RULES',
      value: 'Policy versions',
    },
  ];
}
